                        bi[t][i].s[k][j] = bi[t][i].s[k][j + 1];
                        bi[t][i].s[k][j + 1] = temp;
                    }
                }
            }
        }

        Matrix result = new Matrix(size);
        for (int i = 0; i < size; ++i) {
            result.s[i][i] = 1;
